import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { SAMPLE_VIDEO } from '../data';
import './AuthForms.css';

export default function Login({ onLogin }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [role, setRole] = useState('student');
  const [error, setError] = useState('');

  // Handle input change
  const handleChange = (e) =>
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));

  // Handle form submit
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    try {
      const res = await fetch('http://localhost:5000/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, role }),
      });

      const data = await res.json();
      console.log('Login response:', data);

      if (res.ok && data.token && data.user) {
        // ✅ Save to localStorage
        localStorage.setItem('token', data.token);
        localStorage.setItem('role', data.user.role || role);
        localStorage.setItem('user', JSON.stringify(data.user));

        // Trigger login callback
        onLogin(data.user);

        // Redirect by role
        const userRole = data.user.role || role;
        if (userRole === 'staff') navigate('/staff-dashboard');
        else navigate('/dashboard');
      } else {
        // ❌ Invalid credentials
        setError(data.message || 'Invalid email or password');
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('Something went wrong. Please try again.');
    }
  };

  return (
    <div className={`auth-page ${role}`}>
      {/* Background Video */}
      <div className="video-bg" aria-hidden>
        <video autoPlay muted loop playsInline>
          <source src={SAMPLE_VIDEO} type="video/mp4" />
        </video>
        <div className="overlay" />
      </div>

      {/* Auth Container */}
      <div className="auth-container">
        {/* Header Banner */}
        <div className="welcome-banner">
          <h1>
            🍃 <span>WELCOME TO</span> <span className="brand">NEXORA</span> 🍃
          </h1>
        </div>

        {/* Role Toggle */}
        <div className="role-toggle">
          <button
            type="button"
            className={role === 'student' ? 'active' : ''}
            onClick={() => setRole('student')}
          >
            Student
          </button>
          <button
            type="button"
            className={role === 'staff' ? 'active' : ''}
            onClick={() => setRole('staff')}
          >
            Staff
          </button>
        </div>

        {/* Login Form Card */}
        <div className="auth-card">
          <h2 className="role-heading">
            {role === 'student' ? 'Student Login' : 'Staff Login'}
          </h2>

          <form className="form" onSubmit={handleSubmit}>
            <input
              className="input"
              name="email"
              type="email"
              placeholder={
                role === 'student' ? 'student@school.edu' : 'staff@school.edu'
              }
              value={form.email}
              onChange={handleChange}
              required
            />

            <input
              className="input"
              name="password"
              type="password"
              placeholder="Password"
              value={form.password}
              onChange={handleChange}
              required
            />

            <button className="btn btn-primary" type="submit">
              Login
            </button>

            {error && (
              <p className="error" style={{ color: 'red', marginTop: '8px' }}>
                {error}
              </p>
            )}

            <div style={{ marginTop: 12 }}>
              <span>New? </span>
              <Link to="/signup">Create account</Link>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
